import ast,itertools,math,operator,random,json,types
from pathlib import Path

class Jet:
 def __init__(self,v,d=None): self.v=float(v); self.d=d or {}
 def __float__(self): return self.v
 def __add__(self,b):
  b=b if isinstance(b,Jet) else Jet(b)
  d=self.d.copy()
  for k,v in b.d.items(): d[k]=d.get(k,0.)+v
  return Jet(self.v+b.v,d)
 __radd__=__add__
 def __neg__(self): return Jet(-self.v,{k:-v for k,v in self.d.items()})
 def __sub__(self,b): return self+-b
 def __rsub__(self,b): return b+-self
 def __mul__(self,b):
  b=b if isinstance(b,Jet) else Jet(b)
  d={k:v*b.v for k,v in self.d.items()}
  for k,v in b.d.items(): d[k]=d.get(k,0.)+self.v*v
  return Jet(self.v*b.v,d)
 __rmul__=__mul__
 def reciprocal(self): return Jet(1/self.v,{k:-v/self.v**2 for k,v in self.d.items()})
 def __truediv__(self,b): return self*(b.reciprocal() if isinstance(b,Jet) else 1/b)
 def __rtruediv__(self,b): return self.reciprocal()*b
 def sqrt(self):
  v=math.sqrt(self.v); return Jet(v,{k:d/(2*v) for k,d in self.d.items()})
 def __lt__(self,b): return self.v<float(b)
 def __le__(self,b): return self.v<=float(b)
 def __ge__(self,b): return self.v>=float(b)

def indices(s): return itertools.product(*(range(n) for n in s))
def flatten(x):
 if not isinstance(x,(tuple,list)): return [x],()
 f=[]
 for y in x:
  a,s=flatten(y);f+=a
 return f,(len(x),)+s
class T:
 def __init__(self,data,shape=None):
  self.data,self.shape=flatten(data) if shape is None else (list(data),tuple(shape))
  self.device='cpu';self.dtype='float64'
  assert len(self.data)==math.prod(self.shape)
 def at(self,idx):
  pos=0
  for n,i in zip(self.shape,idx):pos=pos*n+i
  return self.data[pos]
 def val(self,idx,shape):
  idx=idx[len(shape)-len(self.shape):] if self.shape else ()
  return self.at(tuple(0 if n==1 else i for i,n in zip(idx,self.shape)))
 def bin(self,b,fn):
  b=b if isinstance(b,T) else T(b)
  n=max(len(self.shape),len(b.shape)); a=(1,)*(n-len(self.shape))+self.shape; bs=(1,)*(n-len(b.shape))+b.shape
  assert all(x==y or x==1 or y==1 for x,y in zip(a,bs)),(a,bs)
  s=tuple(max(x,y) for x,y in zip(a,bs))
  return T([fn(self.val(i,s),b.val(i,s)) for i in indices(s)],s)
 def map(self,fn):return T([fn(x) for x in self.data],self.shape)
 def __add__(self,b):return self.bin(b,operator.add)
 __radd__=__add__
 def __sub__(self,b):return self.bin(b,operator.sub)
 def __rsub__(self,b):return T(b).bin(self,operator.sub)
 def __mul__(self,b):return self.bin(b,operator.mul)
 __rmul__=__mul__
 def __truediv__(self,b):return self.bin(b,operator.truediv)
 def __floordiv__(self,b):return self.bin(b,operator.floordiv)
 def __and__(self,b):return self.bin(b,operator.and_)
 def __eq__(self,b):return self.bin(b,lambda x,y:float(x)==float(y))
 def __ge__(self,b):return self.bin(b,operator.ge)
 def __invert__(self):return self.map(operator.not_)
 def remainder(self,b):return self.bin(b,operator.mod)
 def square(self):return self*self
 def sqrt(self):return self.map(lambda x:x.sqrt() if isinstance(x,Jet) else math.sqrt(x))
 def reciprocal(self):return self.map(lambda x:1/x)
 def clamp_min(self,b):return self.map(lambda x:x if x>=b else (Jet(b) if isinstance(x,Jet) else b))
 def detach(self):return self.map(lambda x:float(x) if isinstance(x,Jet) else x)
 def long(self):return self.map(int)
 def to(self,dtype):return self.map(float)
 def squeeze(self,dim):
  dim%=len(self.shape);assert self.shape[dim]==1
  return T(self.data,self.shape[:dim]+self.shape[dim+1:])
 def unsqueeze(self,dim):
  dim%=len(self.shape)+1
  return T(self.data,self.shape[:dim]+(1,)+self.shape[dim:])
 def __getitem__(self,key):
  assert key==(None,slice(None,None,None))
  return self.unsqueeze(0)
 def expand_as(self,other):return T([self.val(i,other.shape) for i in indices(other.shape)],other.shape)
 def sum(self,dim=-1,keepdim=False):
  dim%=len(self.shape);s=self.shape[:dim]+self.shape[dim+1:]
  vals=[sum(self.at(i[:dim]+(k,)+i[dim:]) for k in range(self.shape[dim])) for i in indices(s)]
  if keepdim:s=s[:dim]+(1,)+s[dim:]
  return T(vals,s)
 def cumsum(self,dim):
  assert dim==-1
  return T([sum(self.at(i[:-1]+(k,)) for k in range(i[-1]+1)) for i in indices(self.shape)],self.shape)
 def masked_fill(self,mask,value):return where(mask,value,self)
 def argsort(self,dim=-1,stable=False):
  assert dim==-1 and stable
  out=[]
  for i in indices(self.shape[:-1]):out+=sorted(range(self.shape[-1]),key=lambda k:float(self.at(i+(k,))))
  return T(out,self.shape)
 def scatter(self,dim,index,src,add=False):
  assert dim==-1
  out=T(self.data,self.shape)
  for i in indices(index.shape):
   dst=i[:-1]+(int(index.at(i)),); pos=0
   for n,j in zip(out.shape,dst):pos=pos*n+j
   out.data[pos]=out.data[pos]+src.at(i) if add else src.at(i)
  return out
 def scatter_add(self,dim,index,src):return self.scatter(dim,index,src,True)
 def gather(self,dim,index):
  assert dim==-1
  return T([self.at(i[:-1]+(int(index.at(i)),)) for i in indices(index.shape)],index.shape)

def where(c,a,b):
 a=a if isinstance(a,T) else T(a);b=b if isinstance(b,T) else T(b)
 s=(a+b).shape;s=(T([0]*math.prod(s),s)+c).shape
 return T([a.val(i,s) if c.val(i,s) else b.val(i,s) for i in indices(s)],s)
class Torch:
 long='long'
 def arange(self,n,device=None,dtype=None):return T(list(range(n)))
 def zeros_like(self,t):return T([0]*len(t.data),t.shape)
