 where=staticmethod(where)
torch=Torch()

def source_model(file):
 tree=ast.parse(Path(file).read_text());cls=next(n for n in tree.body if isinstance(n,ast.ClassDef))
 out=types.SimpleNamespace();env={'torch':torch,'Model':out}
 for name in ['_rotation_donors','_event_scales','_normalize_product']:
  fn=next((n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name==name),None)
  if fn is None: continue
  fn.decorator_list=[]
  exec(compile(ast.fix_missing_locations(ast.Module(body=[fn],type_ignores=[])),file,'exec'),env)
  setattr(out,name,env[name])
 return out
M=source_model('/workspace/scale_adjacent.py'); A=source_model('/workspace/candidate.py')
modes=['full','constant_tangent','history_mean_tangent','history_reassigned_tangent','action_mean_tangent','action_reassigned_tangent','history_adjacent_tangent','action_adjacent_tangent','scale_adjacent_tangent','scale_half_tangent']

def reference(values,valid,mode,actions):
 out=list(values)
 if mode=='full':return out
 if mode=='constant_tangent':return [.2]*len(values)
 groups=range(1,5) if mode.startswith('action_') else [None]
 for group in groups:
  ids=[j for j in range(len(values)) if valid[j] and (group is None or actions[j]==group)]
  if mode.startswith('scale_'):ids=sorted(ids,key=lambda j:values[j])
  for pos,j in enumerate(ids):
   if 'mean' in mode:out[j]=sum(values[k] for k in ids)/len(ids)
   else:
    shift=1 if 'adjacent' in mode else len(ids)//2
    out[j]=values[ids[(pos+shift)%len(ids)]]
 return out

rng=random.Random(12012026);cases=outputs=ancestor_cases=0;maxerr=maxsum=maxsquare=0.;different=0
for width in [1,2,3,4,6,17,128]:
 for rep in range(30):
  vals=[[rng.choice([.001,.2,.2,1.,1000.]) if rep%3==0 else 10**rng.uniform(-3,3) for j in range(width)] for b in range(8)]
  valid=[[rng.random()<.7 for j in range(width)] for b in range(8)]
  valid[0]=[False]*width;valid[1]=[j==width//2 for j in range(width)]
  acts=[[rng.randrange(6) for j in range(width)] for b in range(8)]
  vt,mt,at=T(vals),T(valid),T(acts)
  for mode in modes:
   got=M._event_scales(vt,mt,mode,at)
   expected=T([reference(v,ok,mode,a) for v,ok,a in zip(vals,valid,acts)])
   for x,y in zip(got.data,expected.data):maxerr=max(maxerr,abs(x-y)/(1+abs(y)))
   assert maxerr<1e-12,(width,rep,mode,maxerr)
   cases+=1;outputs+=len(got.data)
   reverse=M._event_scales(T(vals[::-1]),T(valid[::-1]),mode,T(acts[::-1]))
   assert reverse.data==T([got.data[b*width:(b+1)*width] for b in range(7,-1,-1)]).data
   # Renaming behavioral codes preserves all defined membership groups.
   relabel={0:0,1:3,2:4,3:1,4:2,5:5}
   renamed=M._event_scales(vt,mt,mode,T([[relabel[x] for x in a] for a in acts]))
   assert renamed.data==got.data
   if not mode.startswith('scale_'):
    assert A._event_scales(vt,mt,mode,at).data==got.data;ancestor_cases+=1
   if mode in ['history_adjacent_tangent','history_reassigned_tangent','scale_adjacent_tangent','scale_half_tangent']:
    donor=M._rotation_donors(vt,mt,mode)
    assert vt.gather(-1,donor).data==got.data
    for b in range(8):
     ids=[j for j in range(width) if valid[b][j]]
     assigned=[got.at((b,j)) for j in ids]; original=[vals[b][j] for j in ids]
     assert sorted(assigned)==sorted(original)
     ds=[donor.at((b,j)) for j in ids]
     assert sorted(ds)==ids
     if len(ids)>1:assert all(j!=d for j,d in zip(ids,ds))
     for j in range(width):
      if not valid[b][j]:assert donor.at((b,j))==j
     maxsum=max(maxsum,abs(sum(assigned)-sum(original))/(1+abs(sum(original))))
     maxsquare=max(maxsquare,abs(sum(x*x for x in assigned)-sum(x*x for x in original))/(1+sum(x*x for x in original)))
   if mode=='scale_adjacent_tangent':
    chronological=M._event_scales(vt,mt,'history_adjacent_tangent',at)
    different+=sum(x!=y for x,y in zip(got.data,chronological.data))
assert different>0
print(json.dumps({'array_cases':cases,'scalar_outputs':outputs,'ancestor_cases_exact':ancestor_cases,'reference_max_relative_error':maxerr,'conservation_sum_max_relative_error':maxsum,'conservation_squares_max_relative_error':maxsquare,'scale_adjacent_changed_vs_history_adjacent':different,'seed':12012026}))

