 [[1.,0.,0.,0.],[2.,1.,0.,0.],[3.,-1.,1.,0.],[4.,1.,0.,2.],[5.,0.,1.,0.],[6.,-1.,0.,1.]]]
masks=[[False]*6,[True]*6,[True,False,True,True,False,True],[True]*6]
